SET search_path TO bapc_security_core;
CREATE TABLE certificate_issuers(issuer_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,certificate_pem text NOT NULL,key_reference text NOT NULL,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE certificates(cert_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),node_id uuid REFERENCES mesh_nodes(node_id) ON DELETE CASCADE,issuer_id uuid NOT NULL REFERENCES certificate_issuers(issuer_id),serial_number text UNIQUE NOT NULL,subject_dn text NOT NULL,issued_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,is_revoked boolean NOT NULL DEFAULT false,revocation_reason text);
CREATE TABLE relays(relay_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),node_id uuid UNIQUE REFERENCES mesh_nodes(node_id),region text NOT NULL,endpoint text NOT NULL,load_percent numeric(5,2) NOT NULL DEFAULT 0,latency_ms integer NOT NULL DEFAULT 0,is_available boolean NOT NULL DEFAULT true,last_heartbeat timestamptz);
CREATE TABLE policy_commits(commit_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),policy_payload jsonb NOT NULL,auto_revert_seconds integer NOT NULL DEFAULT 60,status text NOT NULL CHECK(status IN('STAGED','COMMITTED','ROLLED_BACK')),initiated_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),finalized_at timestamptz);
CREATE TABLE incidents(incident_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,severity text NOT NULL,status text NOT NULL,primary_node_id uuid REFERENCES mesh_nodes(node_id),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE command_acknowledgements(command_id uuid NOT NULL,node_id uuid NOT NULL REFERENCES mesh_nodes(node_id),command_type text NOT NULL,issued_at timestamptz NOT NULL,acknowledged_at timestamptz,status text NOT NULL,details jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(command_id,node_id));
